<script setup lang="ts">
import {computed} from 'vue';import type {Node,ArcShape,MaxFlow,Shortest} from '../types/domain';
const props=defineProps<{nodes:Node[];arcs:ArcShape[];flow?:MaxFlow;path?:Shortest;disabled?:string[];mode?:string;idPrefix?:string}>();
const marker=computed(()=>(props.idPrefix||'network')+'-arrow');const coords=computed(()=>new Map(props.nodes.map(n=>[n.node_id,{x:60+n.x*8.8,y:45+n.y*3.8}])));
const shapes=computed(()=>{const groups=new Map<string,ArcShape[]>();for(const a of props.arcs){const key=[a.source,a.target].sort().join('|');groups.set(key,[...(groups.get(key)||[]),a])}return props.arcs.map(a=>{const p=coords.value.get(a.source)!,q=coords.value.get(a.target)!;const group=groups.get([a.source,a.target].sort().join('|'))!.slice().sort((x,y)=>x.arc_id.localeCompare(y.arc_id));const lane=group.findIndex(x=>x.arc_id===a.arc_id)-(group.length-1)/2;const canonical=[a.source,a.target].sort();const cp=coords.value.get(canonical[0])!,cq=coords.value.get(canonical[1])!;const dx=cq.x-cp.x,dy=cq.y-cp.y,L=Math.hypot(dx,dy)||1;const cx=(p.x+q.x)/2-dy/L*lane*35,cy=(p.y+q.y)/2+dx/L*lane*35;const startL=Math.hypot(cx-p.x,cy-p.y)||1,endL=Math.hypot(q.x-cx,q.y-cy)||1;const sx=p.x+(cx-p.x)/startL*13,sy=p.y+(cy-p.y)/startL*13,ex=q.x-(q.x-cx)/endL*15,ey=q.y-(q.y-cy)/endL*15;const path=a.source===a.target?`M ${p.x+12} ${p.y} C ${p.x+60} ${p.y-75} ${p.x-60} ${p.y-75} ${p.x-12} ${p.y}`:`M ${sx} ${sy} Q ${cx} ${cy} ${ex} ${ey}`;const row=props.flow?.arc_flows.find(x=>x.arc_id===a.arc_id);const disabled=props.disabled?.includes(a.arc_id)||row?.disabled;const onPath=props.path?.arc_path.includes(a.arc_id)||false;const inCut=props.flow?.cut_arcs.some(x=>x.arc_id===a.arc_id)||false;const max=Math.max(1,...(props.flow?.arc_flows.map(x=>x.flow)||[1]));const width=props.mode==='path'?(onPath?4:1):row?1+row.flow/max*4:1.5;const nearVertical=group.length>1&&Math.abs(dy)>Math.abs(dx)*1.6;const side=Math.sign((-dy/L)*lane);const labelAnchor=nearVertical&&side!==0?(side>0?"start":"end"):"middle";return {a,row,path,disabled,onPath,inCut,width,labelAnchor,labelX:(p.x+2*cx+q.x)/4+(nearVertical?side*20:0),labelY:(p.y+2*cy+q.y)/4-7,label:props.mode==='path'?a.arc_id:row?`${a.arc_id} ${row.flow}/${row.effective_capacity}`:a.arc_id}})});
</script><template><div class="graph-frame"><svg class="network-graph" viewBox="0 0 1000 490" aria-label="带独立边ID的模拟中转网络"><defs><marker :id="marker" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="var(--muted)"/></marker></defs><g v-for="s in shapes" :key="s.a.arc_id"><path :d="s.path" :class="['edge',{disabled:s.disabled,cut:s.inCut&&mode!=='path',onpath:s.onPath&&mode==='path'}]" :stroke-width="s.width" :marker-end="`url(#${marker})`"><title>{{s.a.arc_id}} / {{s.a.source}}→{{s.a.target}} / 容量{{s.a.capacity}}箱每小时 / 时长{{s.a.travel_minutes}}分钟 / 流{{s.row?.flow??'未计算'}}</title></path><text :x="s.labelX" :y="s.labelY" :text-anchor="s.labelAnchor" class="edge-label">{{s.label}}</text></g><g v-for="n in nodes" :key="n.node_id"><circle :cx="coords.get(n.node_id)!.x" :cy="coords.get(n.node_id)!.y" r="13" :class="['node',{reachable:flow?.source_side.includes(n.node_id)}]"/><text :x="coords.get(n.node_id)!.x" :y="coords.get(n.node_id)!.y+4" text-anchor="middle" class="node-id">{{n.node_id}}</text><text :x="coords.get(n.node_id)!.x" :y="coords.get(n.node_id)!.y+32" text-anchor="middle" class="node-label">{{n.label}}</text></g></svg><div class="graph-legend"><template v-if="mode==='path'"><span><i class="path"/>绿色为独立最短时长路径</span><span>不代表最大流分配</span></template><template v-else><span><i/>线宽为最大流用量；边标为ID 流/有效容量</span><span><i class="cut"/>残量割边</span></template><span><i class="disabled"/>停用边</span></div><p class="caption">平行/反向边按独立ID错开曲线；布局为示意，无真实地理含义。完整容量与时长见逐边表。</p></div></template>
